const items = $input.all();

return items.map((item) => {
  const review = item.json;

  const rating = Number(review.rating || 0);
  const helpfulVotes = Number(review.helpful_votes || 0);
  const confidence = Number(review.confidence || 0);

  const severityScores = {
    low: 5,
    medium: 15,
    high: 25,
    critical: 35,
  };

  const ratingScores = {
    1: 40,
    2: 30,
    3: 20,
    4: 5,
    5: 0,
  };

  const severityScore =
    severityScores[String(review.severity).toLowerCase()] || 0;

  const ratingScore = ratingScores[rating] || 0;

  const helpfulVoteScore = Math.min(helpfulVotes * 2, 15);

  const confidenceScore = Math.min(
    Math.max(confidence * 10, 0),
    10
  );

  const priorityScore = Math.min(
    Math.round(
      severityScore +
      ratingScore +
      helpfulVoteScore +
      confidenceScore
    ),
    100
  );

  let priorityLevel = "LOW";

  if (priorityScore >= 80) {
    priorityLevel = "CRITICAL";
  } else if (priorityScore >= 60) {
    priorityLevel = "HIGH";
  } else if (priorityScore >= 40) {
    priorityLevel = "MEDIUM";
  }

  const requiresAlert =
    priorityLevel === "CRITICAL" ||
    priorityLevel === "HIGH";

  return {
    json: {
      ...review,
      priority_score: priorityScore,
      priority_level: priorityLevel,
      requires_alert: requiresAlert,
    },
  };
});

