const reviews = $input
  .all()
  .map((item) => item.json)
  .filter((review) => review.review_id);

const totalReviews = reviews.length;

function normalizeText(value) {
  return String(value || "").trim().toLowerCase();
}

function toNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

function isTrue(value) {
  return value === true || normalizeText(value) === "true";
}

function countByValue(fieldName, expectedValue) {
  return reviews.filter(
    (review) =>
      normalizeText(review[fieldName]) ===
      normalizeText(expectedValue)
  ).length;
}

function calculateAverage(fieldName) {
  if (totalReviews === 0) {
    return 0;
  }

  const total = reviews.reduce(
    (sum, review) => sum + toNumber(review[fieldName]),
    0
  );

  return Number((total / totalReviews).toFixed(2));
}

const themeCounts = {};

for (const review of reviews) {
  const theme = normalizeText(review.primary_theme);

  if (!theme) {
    continue;
  }

  themeCounts[theme] = (themeCounts[theme] || 0) + 1;
}

let topTheme = "none";
let highestThemeCount = 0;

for (const [theme, count] of Object.entries(themeCounts)) {
  if (count > highestThemeCount) {
    topTheme = theme;
    highestThemeCount = count;
  }
}

const summary = {
  summary_generated_at: new Date().toISOString(),
  total_reviews: totalReviews,
  positive_reviews: countByValue("sentiment", "positive"),
  negative_reviews: countByValue("sentiment", "negative"),
  mixed_reviews: countByValue("sentiment", "mixed"),
  neutral_reviews: countByValue("sentiment", "neutral"),
  high_priority_reviews: countByValue(
    "priority_level",
    "high"
  ),
  critical_reviews: countByValue(
    "priority_level",
    "critical"
  ),
  alerts_required: reviews.filter(
    (review) => isTrue(review.requires_alert)
  ).length,
  average_rating: calculateAverage("rating"),
  average_sentiment_score:
    calculateAverage("sentiment_score"),
  average_priority_score:
    calculateAverage("priority_score"),
  top_theme: topTheme,
};

return [
  {
    json: summary,
  },
];
